import { expect, test } from "../../fixtures";
import { uniqueName } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

test.describe("REV-01 submit vendor for review", () => {
  test(
    "submitting a vendor with all documents extracted moves it to in_review and records an audit event",
    { tag: "@REV-01" },
    async ({ apiAs }) => {
      // Arrange: signed in as the member, create a draft vendor with a unique name.
      const member = await apiAs("member");
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV01 Vendor"),
          category: "software",
          contact_email: `rev01.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();
      expect(vendor.status).toBe("draft");

      // Arrange: upload one document of each kind.
      const documentIds: string[] = [];
      for (const kind of KINDS) {
        const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${vendor.id}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4\n% ${kind} fixture for ${vendor.id}\n%%EOF\n`),
            },
          },
        });
        expect(uploadResponse.status()).toBe(201);
        documentIds.push((await uploadResponse.json()).id);
      }

      // Arrange: wait until every document has finished extraction.
      for (const documentId of documentIds) {
        await expect
          .poll(
            async () => {
              const response = await member.get(`/api/documents/${documentId}`);
              return (await response.json()).status;
            },
            { timeout: 120_000, intervals: [1_000, 2_000, 3_000] },
          )
          .toBe("extracted");
      }

      // Act: submit the vendor for review.
      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert: status and resulting vendor state.
      expect(submitResponse.status()).toBe(200);
      const submitted = await submitResponse.json();
      expect(submitted.status).toBe("in_review");
      expect(submitted.submitted_at).not.toBeNull();

      // Assert: audit trail contains the submission event.
      const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
      expect(auditResponse.status()).toBe(200);
      const audit = await auditResponse.json();
      const actions = (audit.items as { action: string }[]).map((event) => event.action);
      expect(actions).toContain("vendor.submitted");
    },
  );
});
